def recursively_freeze(value):
    """
    Recursively walks ``Mapping``s and ``list``s and converts them to ``FrozenOrderedDict`` and ``tuples``, respectively.
    """
    if isinstance(value, Mapping):
        return FrozenOrderedDict(((k, recursively_freeze(v)) for k, v in value.items()))
    elif isinstance(value, list) or isinstance(value, tuple):
        return tuple(recursively_freeze(v) for v in value)
    return value

def _prefix(subject):
    """
    If the config has a special prefix for emails then this function adds
    this prefix.
    """
    if email().prefix:
        return "{} {}".format(email().prefix, subject)
    else:
        return subject

def matches_any(name, alternates):
    "Return a named group pattern matching list of alternates."
    return "(?P<%s>" % name + "|".join(alternates) + ")"

def get_last_child(node, skip_incorrect=True):
    """Returns last focusable child expression or child statement"""

    def ok_node(node):
        if node is None:
            return None

        assert isinstance(node, (ast.expr, ast.stmt))

        if skip_incorrect and getattr(node, "incorrect_range", False):
            return None

        return node

    def last_ok(nodes):
        for i in range(len(nodes) - 1, -1, -1):
            if ok_node(nodes[i]):
                node = nodes[i]
                if isinstance(node, ast.Starred):
                    if ok_node(node.value):
                        return node.value
                    else:
                        return None
                else:
                    return nodes[i]

        return None

    if isinstance(node, ast.Call):
        # TODO: take care of Python 3.5 updates (Starred etc.)
        if hasattr(node, "kwargs") and ok_node(node.kwargs):
            return node.kwargs
        elif hasattr(node, "starargs") and ok_node(node.starargs):
            return node.starargs
        else:
            kw_values = list(map(lambda x: x.value, node.keywords))
            last_ok_kw = last_ok(kw_values)
            if last_ok_kw:
                return last_ok_kw
            elif last_ok(node.args):
                return last_ok(node.args)
            else:
                return ok_node(node.func)

    elif isinstance(node, ast.BoolOp):
        return last_ok(node.values)

    elif isinstance(node, ast.BinOp):
        if ok_node(node.right):
            return node.right
        else:
            return ok_node(node.left)

    elif isinstance(node, ast.Compare):
        return last_ok(node.comparators)

    elif isinstance(node, ast.UnaryOp):
        return ok_node(node.operand)

    elif isinstance(node, (ast.Tuple, ast.List, ast.Set)):
        return last_ok(node.elts)

    elif isinstance(node, ast.Dict):
        # TODO: actually should pairwise check last value, then last key, etc.
        return last_ok(node.values)

    elif isinstance(
        node, (ast.Index, ast.Return, ast.Assign, ast.AugAssign, ast.Yield, ast.YieldFrom)
    ):
        return ok_node(node.value)

    elif isinstance(node, ast.Delete):
        return last_ok(node.targets)

    elif isinstance(node, ast.Expr):
        return ok_node(node.value)

    elif isinstance(node, ast.Assert):
        if ok_node(node.msg):
            return node.msg
        else:
            return ok_node(node.test)

    elif isinstance(node, ast.Slice):
        # [:]
        if ok_node(node.step):
            return node.step
        elif ok_node(node.upper):
            return node.upper
        else:
            return ok_node(node.lower)

    elif isinstance(node, ast.ExtSlice):
        # [:,:]
        for dim in reversed(node.dims):
            result = get_last_child(dim, skip_incorrect)
            assert result is None or isinstance(result, ast.expr)
            if result is not None:
                return result
        return None

    elif isinstance(node, ast.Subscript):
        result = get_last_child(node.slice, skip_incorrect)
        if result is not None:
            return result
        else:
            return node.value

    elif isinstance(node, ast.Raise):
        if ok_node(node.cause):
            return node.cause
        elif ok_node(node.exc):
            return node.exc

    elif isinstance(node, (ast.For, ast.While, ast.If, ast.With)):
        return True  # There is last child, but I don't know which it will be

    # TODO: pick more cases from here:
    """
    (isinstance(node, (ast.IfExp, ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp))
            # or isinstance(node, ast.FunctionDef, ast.Lambda) and len(node.args.defaults) > 0
                and (node.dest is not None or len(node.values) > 0))

            #"TODO: Import ja ImportFrom"
            # TODO: what about ClassDef ???
    """

    return None

def _m(*names: str) -> str:
    """Get module names"""
    return '.'.join(s for s in names if s)

def _attr(obj: object, attr: str) -> object:
    """Nest `getattr` function."""
    n = obj
    for p in attr.split('.'):
        n = getattr(n, p, None)
        if n is None:
            return None
    return n

def _defaults(args: Sequence[Optional[expr]]) -> Iterator[str]:
    """Literals of the table."""
    yield from (code(unparse(a)) if a is not None else " " for a in args)

def parent(name: str, *, level: int = 1) -> str:
    """Get parent name with level."""
    return name.rsplit('.', maxsplit=level)[0]

def is_public_family(name: str) -> bool:
    """Check the name is come from public modules or not."""
    for n in name.split('.'):
        # Magic name
        if is_magic(n):
            continue
        # Local or private name
        if n.startswith('_'):
            return False
    return True

def walk_body(body: Sequence[stmt]) -> Iterator[stmt]:
    """Traverse around body and its simple definition scope."""
    for node in body:
        if isinstance(node, If):
            yield from walk_body(node.body)
            yield from walk_body(node.orelse)
        elif isinstance(node, Try):
            yield from walk_body(node.body)
            for h in node.handlers:
                yield from walk_body(h.body)
            yield from walk_body(node.orelse)
            yield from walk_body(node.finalbody)
        else:
            yield node

def code(doc: str) -> str:
    """Escape Markdown charters from inline code."""
    doc = doc.replace('|', '&#124;')
    if '&' in doc:
        return f"<code>{doc}</code>"
    elif doc:
        return f"`{doc}`"
    else:
        return " "

def esc_underscore(doc: str) -> str:
    """Escape underscore in names."""
    if doc.count('_') > 1:
        return doc.replace('_', r"\_")
    else:
        return doc

def doctest(doc: str) -> str:
    """Wrap doctest as markdown Python code."""
    keep = False
    docs = []
    lines = doc.splitlines()
    for i, line in enumerate(lines):
        signed = line.startswith(">>> ")
        if signed:
            if not keep:
                docs.append("```python")
                keep = True
        elif keep:
            docs.append("```")
            keep = False
        docs.append(line)
        if signed and i == len(lines) - 1:
            docs.append("```")
            keep = False
    return '\n'.join(docs)

def _table_cell(items: Iterable[str]) -> str:
    """Make a row of table cell."""
    return '|' + '|'.join(f" {t} " for t in items) + '|'

def _type_name(obj: object) -> str:
    """Get type name."""
    return type(obj).__qualname__

def _e_type(*elements: Sequence[Optional[expr]]) -> str:
    """Get element type if type is constants."""
    if not elements:
        return ""
    ts = []
    for element in elements:
        if not element:
            return ""
        t = ""
        for e in element:
            if not isinstance(e, Constant):
                return ""
            nw_t = _type_name(e.value)
            if t and t != nw_t:
                t = "Any"
                break
            t = nw_t
        ts.append(t)
    return '[' + ", ".join(ts) + ']'

def const_type(node: expr) -> str:
    """Constant type inference."""
    if isinstance(node, Constant):
        return _type_name(node.value)
    elif isinstance(node, (Tuple, List, Set)):
        return _type_name(node).lower() + _e_type(node.elts)
    elif isinstance(node, Dict):
        return 'dict' + _e_type(node.keys, node.values)
    elif isinstance(node, Call) and isinstance(node.func, (Name, Attribute)):
        func = unparse(node.func)
        if func in chain({'bool', 'int', 'float', 'complex', 'str'},
                         PEP585.keys(), PEP585.values()):
            return func
    return ANY

def is_coroutine_function(func: Any) -> bool:
    """Return whether *func* is a coroutine function, i.e. a function
    wrapped with `~.gen.coroutine`.

    .. versionadded:: 4.5
    """
    return getattr(func, "__tornado_coroutine__", False)

